-- The forms module (Phase 2 slice 2.4; ADR-0007 pattern V1). Generated by prisma migrate diff,
-- then the hand-written CHECKs, grants and row-level security at the end.
-- CreateSchema
CREATE SCHEMA IF NOT EXISTS "forms";

