-- AddForeignKey
ALTER TABLE "forms"."form" ADD CONSTRAINT "form_published_revision_fkey" FOREIGN KEY ("tenant_id", "id", "published_revision_id") REFERENCES "forms"."form_revision"("tenant_id", "form_id", "id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "forms"."form_revision" ADD CONSTRAINT "form_revision_form_fkey" FOREIGN KEY ("tenant_id", "form_id") REFERENCES "forms"."form"("tenant_id", "id") ON DELETE RESTRICT ON UPDATE RESTRICT;


-- Hand-written: integrity backstops Prisma cannot express. The tenant pattern repeats the
-- kernel's single rule (parseTenantId); the others repeat the module's domain rules.
ALTER TABLE "forms"."form"
  ADD CONSTRAINT "form_tenant_id_check" CHECK ("tenant_id" ~ '^[a-z][a-z0-9-]{1,31}$'),
  ADD CONSTRAINT "form_key_check" CHECK ("key" ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  ADD CONSTRAINT "form_name_check" CHECK (char_length(btrim("name")) > 0),
  ADD CONSTRAINT "form_status_check" CHECK (
    "status" IN ('draft', 'published', 'retired')
    AND ("status" = 'draft') = ("published_revision_id" IS NULL)
  ),
  ADD CONSTRAINT "form_audience_check" CHECK (
    "audience" IN ('anyone', 'portal-user', 'staff', 'staff-roles')
    AND "role_ids" IS NOT NULL
    AND array_position("role_ids", NULL) IS NULL
    AND cardinality("role_ids") <= 32
    AND ("audience" = 'staff-roles') = (cardinality("role_ids") >= 1)
  ),
  ADD CONSTRAINT "form_retention_days_check" CHECK ("retention_days" IS NULL OR "retention_days" BETWEEN 1 AND 36500),
  ADD CONSTRAINT "form_version_check" CHECK ("version" >= 1 AND "revision_count" >= 0);

ALTER TABLE "forms"."form_revision"
  ADD CONSTRAINT "form_revision_number_check" CHECK ("number" >= 1),
  ADD CONSTRAINT "form_revision_content_hash_check" CHECK ("content_hash" ~ '^sha256:[0-9a-f]{64}$'),
  ADD CONSTRAINT "form_revision_documents_check" CHECK (
    jsonb_typeof("json_schema") = 'object' AND jsonb_typeof("ui_schema") = 'object'
  );

-- Grants. The group role "phoenix_app" is created by the cluster bootstrap, never by a
-- migration. A revision is immutable (V1): INSERT and SELECT only. No DELETE anywhere: a form
-- is retired, never removed.
GRANT USAGE ON SCHEMA "forms" TO "phoenix_app";
GRANT SELECT, INSERT, UPDATE ("name", "status", "published_revision_id", "audience", "role_ids", "allow_on_behalf", "retention_days", "revision_count", "version", "updated_at") ON TABLE "forms"."form" TO "phoenix_app";
GRANT SELECT, INSERT ON TABLE "forms"."form_revision" TO "phoenix_app";

-- Row-level security (ADR-0002), enabled and forced (the owner too, security review S2-1),
-- with the reference policy of platform.isolation_probe on every table.
ALTER TABLE "forms"."form" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "forms"."form" FORCE ROW LEVEL SECURITY;
CREATE POLICY "form_tenant_isolation" ON "forms"."form"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());

ALTER TABLE "forms"."form_revision" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "forms"."form_revision" FORCE ROW LEVEL SECURITY;
CREATE POLICY "form_revision_tenant_isolation" ON "forms"."form_revision"
  AS PERMISSIVE FOR ALL TO "phoenix_app"
  USING ("tenant_id" = "platform"."current_tenant_id"())
  WITH CHECK ("tenant_id" = "platform"."current_tenant_id"());
